UPDATE `god2`.`quests` SET `OriginalName`='幫武器店老闆收集一些武鍛材料。' WHERE `Id`=186 AND `OriginalName`='帮武器店老板收集一些武锻材料。';
UPDATE `god2`.`quests` SET `OriginalName`='幫忙法寶屋老闆拿雞飼料給他娘。' WHERE `Id`=187 AND `OriginalName`='帮忙法宝屋老板拿鸡饲料给他娘。';
