UPDATE `god2`.`quests` SET `OriginalName`='李爺爺想要跟你玩猜謎，猜對就讓你把獎品帶回家。' WHERE `Id`=190 AND `OriginalName`='李爷爷想要跟你玩猜谜，猜对就让你把奖品带回家。';
UPDATE `god2`.`quests` SET `OriginalName`='老闆要你去找客棧旁邊的羽嫣姑娘，把她所訂製的衣裳拿給她。' WHERE `Id`=191 AND `OriginalName`='老板要你去找客栈旁边的羽嫣姑娘，把她所订制的衣裳拿给她。';
